import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen4Test {





    @Test
    public void testReduce_WithNegativeNumerator() {
        // GCD of abs(-6) and 9 is 3. Expected: -2/3
        Fraction fraction = Fraction.getFraction(-6, 9);
        Fraction reduced = fraction.reduce();

        assertEquals(-2, reduced.getNumerator());
        assertEquals(3, reduced.getDenominator());
    }




}

