package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Fraction_reduce_TriageGen4Test {









    @Test
    public void testReduce_Identity() {
        // GCD of 1 and 1 is 1.
        Fraction fraction = Fraction.getFraction(1, 1);
        Fraction reduced = fraction.reduce();

        assertEquals(1, reduced.getNumerator());
        assertEquals(1, reduced.getDenominator());
        assertSame(fraction, reduced);
    }
}
